 public Task<Result<IReadOnlyList<QualityTemplateView>>>ListTemplatesAsync(bool includeInactive,int limit,CancellationToken ct)=>tx.ExecuteAsync(async t=>{IQueryable<QCChecklistTemplate>q=db.QCTemplates.AsNoTracking();if(!includeInactive)q=q.Where(x=>x.IsActive);List<QCChecklistTemplate>rows=await q.OrderBy(x=>x.Code).Take(limit).ToListAsync(t);List<QualityTemplateView>views=[];foreach(QCChecklistTemplate x in rows)views.Add(View(x,await db.QCTemplateCriteria.AsNoTracking().Where(c=>c.TemplateId==x.Id).ToListAsync(t)));return Result.Success<IReadOnlyList<QualityTemplateView>>(views);},ct);
 public Task<Result<IReadOnlyList<DefectTypeView>>>ListDefectTypesAsync(bool includeInactive,int limit,CancellationToken ct)=>tx.ExecuteAsync(async t=>{IQueryable<DefectType>q=db.DefectTypes.AsNoTracking();if(!includeInactive)q=q.Where(x=>x.IsActive);return Result.Success<IReadOnlyList<DefectTypeView>>((await q.OrderBy(x=>x.Code).Take(limit).ToListAsync(t)).Select(View).ToArray());},ct);
 public Task<Result<QualityTemplateView>>CreateTemplateAsync(CreateQCTemplateCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{Result<QCChecklistTemplate>made=QCChecklistTemplate.Create(Company,c.Code,c.Name,c.ApplicableJobType,c.ProductTypeCode,Now);if(made.IsFailure||c.Criteria.Count==0)return Result.Failure<QualityTemplateView>(made.IsFailure?made.Error:QualityErrors.Invalid);if(await db.QCTemplates.AnyAsync(x=>x.Code==made.Value.Code,t))return Result.Failure<QualityTemplateView>(QualityErrors.Invalid);List<QCChecklistCriterion>criteria=[];foreach(CreateCriterionCommand x in c.Criteria){Result<QCChecklistCriterion>r=QCChecklistCriterion.Create(Company,made.Value.Id,x.Code,x.Name,x.CriterionType,x.IsRequired,x.SortOrder,x.MinimumValue,x.MaximumValue,x.AllowedChoiceCodes);if(r.IsFailure||criteria.Any(y=>y.Code==r.Value.Code))return Result.Failure<QualityTemplateView>(QualityErrors.Invalid);criteria.Add(r.Value);}db.Add(made.Value);db.AddRange(criteria);History("Template",made.Value.Id,"Created");Log("qc.template.created",made.Value.Id);return Result.Success(View(made.Value,criteria));},ct);
 public Task<Result<QualityTemplateView>>SetTemplateActiveAsync(Guid id,SetQualityActiveCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCChecklistTemplate?x=await db.QCTemplates.SingleOrDefaultAsync(v=>v.Id==id,t);if(x is null)return Result.Failure<QualityTemplateView>(QualityErrors.NotFound);Result r=x.SetActive(c.IsActive,c.Version,Now);if(r.IsFailure)return Result.Failure<QualityTemplateView>(r.Error);History("Template",id,c.IsActive?"Activated":"Deactivated");Log("qc.template.updated",id);return Result.Success(View(x,await db.QCTemplateCriteria.Where(v=>v.TemplateId==id).ToListAsync(t)));},ct);
