 public Task<Result<DefectTypeView>>SetDefectTypeActiveAsync(Guid id,SetQualityActiveCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{DefectType?x=await db.DefectTypes.SingleOrDefaultAsync(v=>v.Id==id,t);if(x is null)return Result.Failure<DefectTypeView>(QualityErrors.NotFound);Result r=x.SetActive(c.IsActive,c.Version,Now);if(r.IsFailure)return Result.Failure<DefectTypeView>(r.Error);History("DefectType",id,c.IsActive?"Activated":"Deactivated");Log("qc.defect_type.updated",id);return Result.Success(View(x));},ct);
 public Task<Result<InspectionView>>StartInspectionAsync(CreateInspectionCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ProductionJob?j=await db.ProductionJobs.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.ProductionJobId,t);QCChecklistTemplate?template=await db.QCTemplates.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.TemplateId&&x.IsActive,t);if(j is null||template is null||j.Status!=ProductionJobStatus.Completed||j.QuantityCompleted is not { } output||output<=0||template.ApplicableJobType is not null&&template.ApplicableJobType!=j.JobType)return Result.Failure<InspectionView>(Error.BusinessRule("qc.production_output_required"));string?uom=await(from i in db.OrderItems join v in db.ProductVariants on i.ProductVariantId equals v.Id join p in db.Products on v.ProductId equals p.Id where i.Id==j.OrderItemId&&i.OrderId==j.OrderId select p.UnitOfMeasureCode).SingleOrDefaultAsync(t);if(string.IsNullOrWhiteSpace(uom))return Result.Failure<InspectionView>(QualityErrors.Invalid);QCInspection?existing=await db.QCInspections.SingleOrDefaultAsync(x=>x.ProductionJobId==j.Id,t);if(existing is not null)return existing.Status is QCInspectionStatus.InProgress or QCInspectionStatus.ManagementReview?Result.Success(View(existing)):Result.Failure<InspectionView>(Error.BusinessRule("qc.inspection.reinspection_not_allowed"));if(c.ParentInspectionId is not null&&!await db.QCInspections.AnyAsync(x=>x.Id==c.ParentInspectionId&&x.Status==QCInspectionStatus.Rejected,t))return Result.Failure<InspectionView>(QualityErrors.Invalid);QCInspection x=QCInspection.Create(Company,j.OrderId,j.OrderItemId,j.Id,template.Id,template.Version,Actor,c.ParentInspectionId,j.ReproductionRequestId,Now);db.Add(x);QCInspectionDisposition pending=QCInspectionDisposition.Create(Company,x.Id,output,uom,0,0,0,"",null,null,Actor,Now).Value;db.Set<QCInspectionDisposition>().Add(pending);History("Inspection",x.Id,"Started",$"Output {output} {uom}");Log("qc.inspection.started",x.Id);return Result.Success(Vi