 public Task<Result<InspectionDispositionView>>SetDispositionAsync(Guid id,SetInspectionDispositionCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);if(i is null||i.Status is QCInspectionStatus.Approved or QCInspectionStatus.Rejected)return Result.Failure<InspectionDispositionView>(QualityErrors.InvalidTransition);QCInspectionDisposition?disposition=await db.Set<QCInspectionDisposition>().SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.InspectionId==id,t);if(disposition is null)return Result.Failure<InspectionDispositionView>(Error.BusinessRule("qc.disposition_required"));Result r=disposition.Replace(c.AcceptedQuantity,c.RejectedQuantity,c.ReproductionRequiredQuantity,c.AcceptedReason,c.RejectedReason,c.ReproductionReason,c.Version,Actor,Now);if(r.IsFailure)return Result.Failure<InspectionDispositionView>(r.Error);History("Inspection",id,"DispositionRecorded",$"{disposition.AcceptedQuantity}+{disposition.RejectedQuantity}+{disposition.ReproductionRequiredQuantity} {disposition.UomCode}");Log("qc.inspection.disposition",id);return Result.Success(DispositionView(disposition));},ct);
 public Task<Result>ValidateWorkflowCompletionAsync(Guid orderId,string? outcome,CancellationToken ct)=>tx.ExecuteAsync(async t=>{List<ProductionJob>jobs=await db.ProductionJobs.Where(x=>x.OrderId==orderId&&x.Status==ProductionJobStatus.Completed).OrderBy(x=>x.OrderItemId).ThenBy(x=>x.Id).ToListAsync(t);if(jobs.Count==0)return Result.Failure(Error.BusinessRule("qc.workflow_evidence_required"));foreach(ProductionJob j in jobs){QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.ProductionJobId==j.Id&&(x.Status==QCInspectionStatus.Approved||x.Status==QCInspectionStatus.Rejected),t);if(i is null)return Result.Failure(Error.BusinessRule("qc.workflow_evidence_required"));QCInspectionDisposition?d=await db.Set<QCInspectionDisposition>().SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.InspectionId==i.Id,t);if(d is null||d.AcceptedQuantity+d.RejectedQuantity+d.ReproductionRequiredQuantity!=d.InspectableQuantity)return Result.Failure(Error.BusinessRule("qc.workflow_evidence_required"));if(i.Status==QCInspectionStatus.Approved){if(d.RejectedQuantity>0||d.ReproductionRequiredQuantity>0||!string.Equals(outcome,"Approve",StringComparison.OrdinalIgnoreCase))return Result.Failure(Error.BusinessRule("qc.workflow_evidence_required"));continue;}if(!string.Equals(outcome,"Approve",StringComparison.OrdinalIgnoreCase)&&!string.Equals(outcome,"Reject",StringComparison.OrdinalIgnoreCase))return Result.Failure(Error.BusinessRule("qc.workflow_evidence_required"));decimal unresolved=d.RejectedQuantity+d.ReproductionRequiredQuantity;if(unresolved<=0)return Result.Failure(Error.BusinessRule("qc.workflow_unresolved_quantity"));decimal resolved=0;if(d.ReproductionRequiredQuantity>0){List<ReproductionRequest>requests=await db.ReproductionRequests.AsNoTracking().Where(x=>x.CompanyId==Company&&x.SourceInspectionId==i.Id).ToListAsync(t);foreach(ReproductionRequest request in requests){decimal required=request.Quantity;List<ProductionJob>replacementJobs=await db.ProductionJobs.Where(x=>x.CompanyId==Company&&x.ReproductionRequestId==request.Id&&x.Status==ProductionJobStatus.Completed).ToListAsync(t);foreach(ProductionJob replacement in replacementJobs){QCInspection?replacementInspection=await db.QCInspections.SingleOrDefaultAsync(x=>x.ProductionJobId==replacement.Id&&x.Status==QCInspectionStatus.Approved,t);if(replacementInspection is null)continue;QCInspectionDisposition?replacementDisposition=await db.Set<QCInspectionDisposition>().AsNoTracking().SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.InspectionId==replacementInspection.Id,t);if(replacementDisposition is null||replacementDisposition.RejectedQuantity>0||replacementDisposition.ReproductionRequiredQuantity>0)continue;resolved+=Math.Min(required,replacementDisposition.AcceptedQuantity);if(resolved>=d.ReproductionRequiredQuantity)break;}if(resolved>=d.ReproductionRequiredQuantity)break;}}if(resolved<d.ReproductionRequiredQuantity||d.RejectedQuantity>0)return Result.Failure(Error.BusinessRule("qc.workflow_unresolved_quantity"));if(!string.Equals(outcome,"Approve",StringComparison.OrdinalIgnoreCase))return Result.Failure(Error.BusinessRule("qc.workflow_evidence_required"));}return Result.Success();},ct);
 public Task<Result<InspectionView>>GetInspectionAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?x=await db.QCInspections.AsNoTracking().SingleOrDefaultAsync(v=>v.Id==id,t);if(x is null)return Result.Failure<InspectionView>(QualityErrors.NotFound);QCInspectionDisposition?disposition=await db.Set<QCInspectionDisposition>().AsNoTracking().SingleOrDefaultAsync(v=>v.CompanyId==Company&&v.InspectionId==id,t);return Result.Success(View(x,disposition));},ct);
 public Task<Result>RecordResultAsync(Guid id,RecordCriteriaResultCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);QCChecklistCriterion?criterion=await db.QCTemplateCriteria.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.CriterionId,t);if(i is null||criterion is null||criterion.TemplateId!=i.TemplateId||i.Status is not(QCInspectionStatus.InProgress or QCInspectionStatus.ManagementReview)||await db.QCCriteriaResults.AnyAsync(x=>x.InspectionId==id&&x.TemplateCriterionId==c.CriterionId,t))return Result.Failure(QualityErrors.Invalid);Result<QCCriteriaResult>r=QCCriteriaResult.Create(Company,id,criterion,c.PassFailValue,c.NumericValue,c.TextValue,c.ChoiceCode,Actor,Now);if(r.IsFailure)return Result.Failure(r.Error);db.Add(r.Value);History("Inspection",id,"CriterionRecorded",criterion.Code);Log("qc.result.recorded",id);return Result.Success();},ct);
 public Task<Result>RecordDefectAsync(Guid id,RecordDefectCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);DefectType?d=await db.DefectTypes.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==c.DefectTypeId&&x.IsActive,t);QCInspectionDisposition?disposition=await db.Set<QCInspectionDisposition>().SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.InspectionId==id,t);decimal defectTotal=await db.QCDefects.Where(x=>x.InspectionId==id).SumAsync(x=>(decimal?)x.Quantity,t)??0;if(i is null||d is null||disposition is null||i.Status is not(QCInspectionStatus.InProgress or QCInspectionStatus.ManagementReview)||c.Quantity<=0||defectTotal+c.Quantity>disposition.InspectableQuantity)return Result.Failure(QualityErrors.Invalid);if(c.CriteriaResultId is not null&&!await db.QCCriteriaResults.AnyAsync(x=>x.Id==c.CriteriaResultId&&x.InspectionId==id,t)||c.EvidenceFileVersionId is not null&&!await db.FileVersions.AnyAsync(x=>x.Id==c.EvidenceFileVersionId,t))return Result.Failure(QualityErrors.Invalid);Result<QCDefect>r=QCDefect.Create(Company,id,c.CriteriaResultId,d.Id,c.Quantity,c.Severity,c.Notes,c.EvidenceFileVersionId,Actor,Now);if(r.IsFailure)return Result.Failure(r.Error);db.Add(r.Value);History("Inspection",id,"DefectRecorded",d.Code);Log("qc.defect.recorded",id);return Result.Success();},ct);
 public Task<Result<InspectionView>>ApproveAsync(Guid id,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);if(i is null)return Result.Failure<InspectionView>(QualityErrors.NotFound);QCInspectionDisposition?disposition=await db.Set<QCInspectionDisposition>().SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.InspectionId==id,t);if(disposition is null||disposition.AcceptedQuantity+disposition.RejectedQuantity+disposition.ReproductionRequiredQuantity!=disposition.InspectableQuantity)return Result.Failure<InspectionView>(Error.BusinessRule("qc.disposition_required"));if(disposition.RejectedQuantity>0||disposition.ReproductionRequiredQuantity>0)return Result.Failure<InspectionView>(Error.BusinessRule("qc.approval_requires_full_acceptance"));int required=await db.QCTemplateCriteria.CountAsync(x=>x.TemplateId==i.TemplateId&&x.IsRequired,t),done=await db.QCCriteriaResults.CountAsync(x=>x.InspectionId==id&&x.IsRequired,t);if(done<required)return Result.Failure<InspectionView>(QualityErrors.CriteriaIncomplete);bool blocking=await(from d in db.QCDefects join k in db.DefectTypes on d.DefectTypeId equals k.Id where d.InspectionId==id&&k.IsBlocking select d.Id).AnyAsync(t);if(blocking)return Result.Failure<InspectionView>(QualityErrors.BlockingDefect);return Finish(i,i.Approve(version,Now),"Approved",null);},ct);
 public Task<Result<InspectionView>>SuspendAsync(Guid id,QualityReasonCommand c,CancellationToken ct)=>Change(id,c.Version,"Suspended",c.Reason,(x,n)=>x.Suspend(c.Reason,c.Version,n),ct);public Task<Result<InspectionView>>ReviewAsync(Guid id,QualityReasonCommand c,CancellationToken ct)=>Change(id,c.Version,"ManagementReview",c.Reason,(x,n)=>x.Review(c.Reason,c.Version,n),ct);public Task<Result<InspectionView>>RejectAsync(Guid id,QualityReasonCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);QCInspectionDisposition?disposition=await db.Set<QCInspectionDisposition>().SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.InspectionId==id,t);if(disposition is null||disposition.AcceptedQuantity+disposition.RejectedQuantity+disposition.ReproductionRequiredQuantity!=disposition.InspectableQuantity||disposition.RejectedQuantity+disposition.ReproductionRequiredQuantity<=0)return Result.Failure<InspectionView>(Error.BusinessRule("qc.rejection_disposition_required"));return i is null?Result.Failure<InspectionView>(QualityErrors.NotFound):Finish(i,i.Reject(c.Reason,c.Version,Now),"Rejected",c.Reason);},ct);
 private Task<Result<InspectionView>>Change(Guid id,long v,string evt,string?summary,Func<QCInspection,DateTimeOffset,Result>f,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.SingleOrDefaultAsync(x=>x.Id==id,t);return i is null?Result.Failure<InspectionView>(QualityErrors.NotFound):Finish(i,f(i,Now),evt,summary);},ct);private Result<InspectionView>Finish(QCInspection i,Result r,string evt,string?summary){if(r.IsFailure)return Result.Failure<InspectionView>(r.Error);History("Inspection",i.Id,evt,summary);Log($"qc.inspection.{evt.ToLowerInvariant()}",i.Id);return Result.Success(View(i));}
 public Task<Result<ReproductionView>>RequestReproductionAsync(Guid inspectionId,CreateReproductionCommand c,CancellationToken ct)=>tx.ExecuteAsync(async t=>{QCInspection?i=await db.QCInspections.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==inspectionId,t);QCInspectionDisposition?disposition=await db.Set<QCInspectionDisposition>().AsNoTracking().SingleOrDefaultAsync(x=>x.CompanyId==Company&&x.InspectionId==inspectionId,t);if(i is null||i.Status!=QCInspectionStatus.Rejected||disposition is null||c.Quantity<=0||c.Quantity>disposition.ReproductionRequiredQuantity)return Result.Failure<ReproductionView>(QualityErrors.ReproductionNotAllowed);ReproductionRequest?existing=await db.ReproductionRequests.SingleOrDefaultAsync(x=>x.SourceInspectionId==inspectionId,t);if(existing is not null)return Result.Success(View(existing));ProductionJob source=await db.ProductionJobs.AsNoTracking().SingleAsync(x=>x.Id==i.ProductionJobId,t);Guid root=source.RootProductionJobId??source.Id;int depth=source.ReproductionDepth+1;Result<ReproductionRequest>r=ReproductionRequest.Create(Company,i.Id,i.OrderId,i.OrderItemId,source.Id,root,c.RequestedStage,c.Quantity,c.Reason,Actor,depth,Now);if(r.IsFailure)return Result.Failure<ReproductionView>(r.Error);db.Add(r.Value);History("Reproduction",r.Value.Id,"Requested",c.Reason);Log("qc.reproduction.requested",r.Value.Id);return Result.Success(View(r.Value));},ct);
 public Task<Result<IReadOnlyList<Guid>>>CreateReproductionJobsAsync(Guid requestId,long version,CancellationToken ct)=>tx.ExecuteAsync(async t=>{ReproductionRequest?r=await db.ReproductionRequests.SingleOrDefaultAsync(x=>x.Id==requestId,t);if(r is null)return Result.Failure<IReadOnlyList<Guid>>(QualityErrors.NotFound);List<ProductionJob>existing=await db.ProductionJobs.Where(x=>x.ReproductionRequestId==requestId).ToListAsync(t);if(existing.Count>0)return Result.Success<IReadOnlyList<Guid>>(existing.Select(x=>x.Id).ToArray());ProductionJob source=await db.ProductionJobs.AsNoTracking().SingleAsync(x=>x.Id==r.SourceProductionJobId,t);List<(ProductionJobType,Guid?,Guid?,Guid?)>specs=[];if(r.RequestedStage is ReproductionStage.DesignPreparation or ReproductionStage.FullItem)specs.Add((ProductionJobType.DesignPreparation,null,null,null));if(r.RequestedStage is ReproductionStage.Print or ReproductionStage.FullItem){var ops=await db.OrderPrintOperations.AsNoTracking().Where(x=>x.OrderItemId==r.OrderItemId&&x.IsActive).ToListAsync(t);foreach(var op in ops)specs.Add((ProductionJobType.Print,op.Id,op.ArtworkVersionId,op.FileVersionId));if(r.RequestedStage==ReproductionStage.Print&&specs.Count==0)return Result.Failure<IReadOnlyList<Guid>>(QualityErrors.Invalid);}if(r.RequestedStage is ReproductionStage.HeatPress or ReproductionStage.FullItem)specs.Add((ProductionJobType.HeatPress,null,null,null));List<ProductionJob>jobs=[];foreach(var s in specs){Result<ProductionJob>made=ProductionJob.CreateReproduction(Company,r.OrderId,r.OrderItemId,s.Item2,s.Item1,r.Id,source.Id,r.RootProductionJobId,r.Depth,s.Item3,s.Item4,Now);if(made.IsFailure)return Result.Failure<IReadOnlyList<Guid>>(made.Error);jobs.Add(made.Value);db.Add(made.Value);db.ProductionJobHistory.Add(ProductionJobHistory.Create(Company,made.Value.Id,"Created",Actor,Now,$"Reproduction {r.Id}"));}Result marked=r.MarkJobsCreated(version,Now);if(marked.IsFailure)return Result.Failure<IReadOnlyList<Guid>>(marked.Error);History("Reproduction",r.Id,"JobsCreated",jobs.Count.ToString());Log("qc.reproduction.jobs_created",r.Id);return Result.Success<IReadOnlyList<Guid>>(jobs.Select(x=>x.Id).ToArray());},ct);
 public Task<Result<IReadOnlyList<QualityHistoryView>>>HistoryAsync(Guid id,CancellationToken ct)=>tx.ExecuteAsync(async t=>Result.Success<IReadOnlyList<QualityHistoryView>>((await db.QCHistory.AsNoTracking().Where(x=>x.EntityId==id).OrderBy(x=>x.OccurredAtUtc).ThenBy(x=>x.Id).ToListAsync(t)).Select(x=>new QualityHistoryView(x.Id,x.EntityType,x.EntityId,x.EventType,x.ActorUserId,x.OccurredAtUtc,x.Summary)).ToArray()),ct);
 public Task<Result<QualityAnalyticsView>>AnalyticsAsync(DateTimeOffset start,DateTimeOffset end,int top,CancellationToken ct)=>tx.ExecuteAsync(async t=>{if(end<=start||top is<1 or>50)return Result.Failure<QualityAnalyticsView>(QualityErrors.Invalid);var q=db.QCInspections.AsNoTracking().Where(x=>x.CreatedAtUtc>=start&&x.CreatedAtUtc<end);long total=await q.LongCountAsync(t),approved=await q.LongCountAsync(x=>x.Outcome==QCOutcome.Approved,t),rejected=await q.LongCountAsync(x=>x.Outcome==QCOutcome.Rejected,t),suspended=await q.LongCountAsync(x=>x.Status==QCInspectionStatus.Suspended,t),repros=await db.ReproductionRequests.LongCountAsync(x=>x.RequestedAtUtc>=start&&x.RequestedAtUtc<end,t);var defects=await(from d in db.QCDefects join k in db.DefectTypes on d.DefectTypeId equals k.Id where d.RecordedAtUtc >= start && d.RecordedAtUtc < end group d by new{k.Code,k.Name}into g orderby g.Count() descending select new DefectFrequencyView(g.Key.Code,g.Key.Name,g.LongCount(),g.Sum(x=>x.Quantity))).Take(top).ToListAsync(t);return Result.Success(new QualityAnalyticsView(total,approved,rejected,suspended,repros,defects));},ct);
 private void History(string entity,Guid id,string evt,string?summary=null)=>db.QCHistory.Add(QCHistory.Create(Company,entity,id,evt,Actor,Now,summary));private void Log(string action,Guid id)=>audit.Write(new(action,"quality",id.ToString(),ChangeKind:AuditChangeKind.Modified));
